public with sharing class ContactLookupAction {

    @InvocableMethod(label='Find Contact by Email' description='Finds an existing contact by email and returns the contact ID.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();

        if (requests == null || requests.isEmpty()) {
            return results;
        }

        Map<Integer, String> indexToEmail = new Map<Integer, String>();
        Set<String> uniqueEmails = new Set<String>();

        for (Integer i = 0; i < requests.size(); i++) {
            Request req = requests[i];
            String email = normalizeEmail(req == null ? null : req.email);

            if (String.isBlank(email)) {
                results.add(new Result(null, false));
            } else {
                indexToEmail.put(i, email);
                uniqueEmails.add(email);
                results.add(new Result(null, false));
            }
        }

        if (!uniqueEmails.isEmpty()) {
            Map<String, Contact> firstContactByEmail = new Map<String, Contact>();

            for (Contact c : [
                SELECT Id, Email, CreatedDate
                FROM Contact
                WHERE Email IN :uniqueEmails
                ORDER BY CreatedDate ASC, Id ASC
            ]) {
                String normalized = normalizeEmail(c.Email);
                if (normalized != null && !firstContactByEmail.containsKey(normalized)) {
                    firstContactByEmail.put(normalized, c);
                }
            }

            for (Integer i : indexToEmail.keySet()) {
                Contact c = firstContactByEmail.get(indexToEmail.get(i));
                if (c != null) {
                    Result result = results.get(i);
                    result.found = true;
                    result.contactId = c.Id;
                }
            }
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        return email.trim().toLowerCase();
    }

    public class Request {
        @InvocableVariable(label='Email' required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(label='Contact ID')
        public Id contactId;

        @InvocableVariable(label='Found')
        public Boolean found;

        public Result() {
        }

        public Result(Id contactId, Boolean found) {
            this.contactId = contactId;
            this.found = found;
        }
    }
}
