private class RenewalServiceTest {
    private static fflib_ApexMocks mocks;
    private static IOpportunitiesSelector mockSelector;
    private static fflib_ISObjectUnitOfWork mockUow;

    private static void initMocks() {
        mocks = new fflib_ApexMocks();
        mockSelector = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        mockUow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.Selector.setMock(Opportunity.SObjectType, mockSelector);
        Application.UnitOfWork.setMock(mockUow);
    }

    @IsTest
    static void createRenewals_createsRenewalAndReminderTask() {
        initMocks();

        Id oppId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id accountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id ownerId = fflib_IDGenerator.generate(User.SObjectType);
        Date closeDate = Date.newInstance(2025, 1, 15);
        Decimal amount = 1000.00;

        Opportunity won = new Opportunity(
            Id = oppId,
            Name = 'Big Deal',
            AccountId = accountId,
            OwnerId = ownerId,
            StageName = 'Closed Won',
            CloseDate = closeDate,
            Amount = amount
        );

        Set<Id> oppIds = new Set<Id>{ oppId };
        mocks.startStubbing();
        mocks.when(mockSelector.selectById(oppIds)).thenReturn(new List<Opportunity>{ won });
        mocks.stopStubbing();

        RenewalService.createRenewals(oppIds);

        mocks.verify(mockSelector, 1).selectById(oppIds);

        fflib_ArgumentCaptor renewalCaptor = fflib_ApexMocks.newArgumentCaptor();
        mocks.verify(mockUow, 1).registerNew((Opportunity) renewalCaptor.capture());
        Opportunity renewal = (Opportunity) renewalCaptor.getValue();

        System.assertEquals(won.Name + ' - Renewal', renewal.Name);
        System.assertEquals(won.AccountId, renewal.AccountId);
        System.assertEquals('Prospecting', renewal.StageName);
        System.assertEquals(closeDate.addYears(1), renewal.CloseDate);
        System.assertEquals((amount * RenewalService.UPLIFT).setScale(2), renewal.Amount);

        fflib_ArgumentCaptor taskCaptor = fflib_ApexMocks.newArgumentCaptor();
        fflib_ArgumentCaptor relatedRenewalCaptor = fflib_ApexMocks.newArgumentCaptor();
        mocks.verify(mockUow, 1).registerNew((Task) taskCaptor.capture(), Task.WhatId, (SObject) relatedRenewalCaptor.capture());
        Task reminder = (Task) taskCaptor.getValue();
        Opportunity relatedRenewal = (Opportunity) relatedRenewalCaptor.getValue();

        System.assertEquals('Prepare renewal for ' + won.Name, reminder.Subject);
        System.assertEquals(won.OwnerId, reminder.OwnerId);
        System.assertEquals(renewal.CloseDate.addDays(-60), reminder.ActivityDate);
        System.assertEquals(renewal, relatedRenewal);
        System.assertNotEquals(won.Id, relatedRenewal.Id);

        mocks.verify(mockUow, 1).commitWork();
    }

