        };
        Set<Schema.SObjectField> selectedFields = new Set<Schema.SObjectField>(fields);

        Schema.FieldSet creditReviewFieldSet = Schema.SObjectType.Account.fieldSets.getMap().get('Credit_Review');
        if (creditReviewFieldSet != null) {
            for (Schema.FieldSetMember fieldSetMember : creditReviewFieldSet.getFields()) {
                Schema.SObjectField field = fieldSetMember.getSObjectField();
                if (field != null && !selectedFields.contains(field)) {
                    fields.add(field);
                    selectedFields.add(field);
                }
            }
        }
        return fields;
    }

