public with sharing class ContactPhoneCleanup {
    public static Map<Id, String> normalizePhones(List<Id> contactIds) {
        Map<Id, String> errors = new Map<Id, String>();

        if (contactIds == null || contactIds.isEmpty()) {
            return errors;
        }

        List<Contact> contacts = [
            SELECT Id, Phone
            FROM Contact
            WHERE Id IN :contactIds
        ];

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : contacts) {
            // Only normalize contacts that actually have a phone value.
            if (String.isNotBlank(contact.Phone)) {
                contact.Phone = contact.Phone.replaceAll('[^0-9+]', '');
                contactsToUpdate.add(contact);
            }
        }

        // Avoid an unnecessary DML call when no contacts need updating.
        if (contactsToUpdate.isEmpty()) {
            return errors;
        }

        List<Database.SaveResult> saveResults = Database.update(contactsToUpdate, false);

        for (Database.SaveResult result : saveResults) {
            if (!result.isSuccess()) {
                errors.put(result.getId(), result.getErrors()[0].getMessage());
            }
        }

        return errors;
    }
}
