public class AccountCountrySync {
    public static void syncContacts(List<Account> newAccounts, Map<Id, Account> oldAccounts) {
        if (newAccounts == null || oldAccounts == null) {
            return;
        }

        Set<Id> changedAccountIds = new Set<Id>();
        Map<Id, String> oldBillingCountryByAccountId = new Map<Id, String>();
        Map<Id, String> newBillingCountryByAccountId = new Map<Id, String>();
        Set<String> oldBillingCountryValues = new Set<String>();

        for (Account acc : newAccounts) {
            Account old = oldAccounts.get(acc.Id);
            if (old != null && acc.BillingCountry != old.BillingCountry) {
                changedAccountIds.add(acc.Id);
                oldBillingCountryByAccountId.put(acc.Id, old.BillingCountry);
                newBillingCountryByAccountId.put(acc.Id, acc.BillingCountry);
                if (String.isNotBlank(old.BillingCountry)) {
                    oldBillingCountryValues.add(old.BillingCountry);
                }
            }
        }

        if (changedAccountIds.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact con : [
                SELECT Id, AccountId, MailingCountry
                FROM Contact
                WHERE AccountId IN :changedAccountIds
                AND (MailingCountry = null
                     OR MailingCountry = ''
                     OR MailingCountry IN :oldBillingCountryValues)
        ]) {
            if (!newBillingCountryByAccountId.containsKey(con.AccountId)) {
                continue;
            }

            String previousBillingCountry = oldBillingCountryByAccountId.get(con.AccountId);
            String currentBillingCountry = newBillingCountryByAccountId.get(con.AccountId);

            if (String.isBlank(con.MailingCountry) || con.MailingCountry == previousBillingCountry) {
                if (con.MailingCountry != currentBillingCountry) {
                    con.MailingCountry = currentBillingCountry;
                    contactsToUpdate.add(con);
                }
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
