import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

export default class ContactSearch extends LightningElement {
    searchTerm = '';
    contacts = [];
    error;
    _debounceTimeout;
    _latestRequestId = 0;

    handleChange(event) {
        this.searchTerm = event.target.value;
        const trimmed = this.searchTerm.trim();

        if (trimmed.length < 2) {
            window.clearTimeout(this._debounceTimeout);
            this._debounceTimeout = undefined;
            this.contacts = [];
            this.error = undefined;
            this._latestRequestId++;
            return;
        }

        window.clearTimeout(this._debounceTimeout);
        this._debounceTimeout = window.setTimeout(() => {
            this.runSearch(trimmed);
        }, 300);
    }

    runSearch(trimmed) {
        if (!this.isConnected) {
            return;
        }

        const requestId = ++this._latestRequestId;

        searchContacts({ searchTerm: trimmed })
            .then((result) => {
                if (!this.isConnected || requestId !== this._latestRequestId) {
                    return;
                }

                this.contacts = result || [];
                this.error = undefined;
            })
            .catch((error) => {
                if (!this.isConnected || requestId !== this._latestRequestId) {
                    return;
                }

                this.contacts = [];
                this.error = error.body.message;
            });
    }

    disconnectedCallback() {
        window.clearTimeout(this._debounceTimeout);
        this._debounceTimeout = undefined;
        this._latestRequestId++;
    }
}
