import { LightningElement } from 'lwc';
import register from '@salesforce/apex/RegistrationController.register';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

export default class EventRegistrationForm extends LightningElement {
    fullName = '';
    email = '';
    company = '';

    handleChange(event) {
        const field = event.target.dataset.field;
        if (field === 'fullName') {
            this.fullName = event.detail.value;
        } else if (field === 'email') {
            this.email = event.detail.value;
        } else if (field === 'company') {
            this.company = event.detail.value;
        }
    }

    handleRegister() {
        const emailInput = this.template.querySelector('[data-field="email"]');
        const domain = this.email ? this.email.split('@')[1]?.toLowerCase() : '';

        if (['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com'].includes(domain)) {
            emailInput.setCustomValidity('Use your work email address.');
        } else {
            emailInput.setCustomValidity('');
        }

        const inputs = this.template.querySelectorAll('lightning-input');
        let isValid = true;
        inputs.forEach(input => {
            if (!input.reportValidity()) {
                isValid = false;
            }
        });

        if (!isValid) {
            return;
        }

        register({ fullName: this.fullName, email: this.email, company: this.company })
            .then(() => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'success',
                        title: 'Registered'
                    })
                );
            })
            .catch(error => {
                this.dispatchEvent(
                    new ShowToastEvent({
                        variant: 'error',
                        title: 'Registration failed',
                        message: error.body.message
                    })
                );
            });
    }
}
