import { LightningElement, api, track } from 'lwc';

let idCounter = 0;

export default class StatusListbox extends LightningElement {
    @api label;
    _options = [];
    _value = '';
    @track activeIndex = -1;

    connectedCallback() {
        this.baseId = `statusListbox-${++idCounter}`;
    }

    @api
    get options() {
        return this._options;
    }

    set options(value) {
        this._options = Array.isArray(value) ? value : [];
        this.syncActiveIndex();
    }

    @api
    get value() {
        return this._value;
    }

    set value(value) {
        this._value = value == null ? '' : value;
        this.syncActiveIndex();
    }

    syncActiveIndex() {
        if (!this._options || this._options.length === 0) {
            this.activeIndex = -1;
            return;
        }

        if (this._value !== '') {
            const index = this._options.findIndex(
                (option) => option.value === this._value
            );
            if (index >= 0) {
                this.activeIndex = index;
                return;
            }
        }

        this.activeIndex = 0;
    }

    get processedOptions() {
        return this._options.map((option, index) => ({
            value: option.value,
            label: option.label,
            id: this.optionId(index),
            index: index,
            selected: option.value === this._value,
            active: index === this.activeIndex
        }));
    }

    get activeOptionId() {
        if (this.activeIndex >= 0 && this.activeIndex < this._options.length) {
            return this.optionId(this.activeIndex);
        }
        return '';
    }

    optionId(index) {
        return `${this.baseId}-option-${index}`;
    }

    handleKeydown(event) {
        const key = event.key;
        const validKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
        if (!validKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        switch (key) {
            case 'ArrowDown':
                this.moveActive(1);
                break;
            case 'ArrowUp':
                this.moveActive(-1);
                break;
            case 'Home':
                this.activeIndex = 0;
                break;
            case 'End':
                this.activeIndex = this._options.length - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectActiveOption();
                break;
        }
    }

    moveActive(delta) {
        const maxIndex = this._options.length - 1;
        if (maxIndex < 0) {
            return;
        }

        let newIndex = this.activeIndex + delta;
        if (newIndex < 0) {
            newIndex = 0;
        } else if (newIndex > maxIndex) {
            newIndex = maxIndex;
        }

        this.activeIndex = newIndex;
    }

    selectActiveOption() {
        const option = this._options[this.activeIndex];
        if (!option) {
            return;
        }
        this.selectOption(option.value);
    }

    handleOptionClick(event) {
        const index = parseInt(event.currentTarget.dataset.index, 10);
        if (index >= 0 && index < this._options.length) {
            this.activeIndex = index;
            this.selectOption(this._options[index].value);
            this.template.querySelector('ul').focus();
        }
    }

    selectOption(value) {
        if (value === this._value) {
            return;
        }
        this.dispatchEvent(
            new CustomEvent('change', {
                detail: { value },
                bubbles: true,
                composed: true
            })
        );
    }
}
