import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api
    get tasks() {
        return this._tasks;
    }

    set tasks(value) {
        this._tasks = value || [];
        this.items = this._tasks.map((task) => ({ ...task }));
        this.nextId = this.getNextId();
    }

    get displayHeading() {
        return this.heading ? this.heading.toUpperCase() : '';
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    getNextId() {
        const max = this.items.reduce((max, task) => {
            const match = String(task.id).match(/^new-(\d+)$/);
            return match ? Math.max(max, parseInt(match[1], 10)) : max;
        }, 0);
        return max + 1;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const label = this.newLabel.trim();
        if (!label) {
            return;
        }
        this.items = [
            ...this.items,
            { id: `new-${this.nextId++}`, label, done: false }
        ];
        this.newLabel = '';
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label } }));
    }

    handleToggle(event) {
        const taskId = event.target.dataset.id;
        const task = this.items.find((t) => String(t.id) === taskId);
        if (task) {
            this.items = this.items.map((t) =>
                String(t.id) === taskId ? { ...t, done: !t.done } : t
            );
        }
    }
}
