public with sharing class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    public override npsp.DmlWrapper run(
        List<SObject> newList,
        List<SObject> oldList,
        npsp.TDTM_Runnable.Action triggerAction,
        Schema.DescribeSObjectResult objResult
    ) {
        npsp.DmlWrapper dmlWrapper = new npsp.DmlWrapper();

        if (triggerAction != npsp.TDTM_Runnable.Action.AfterInsert
            && triggerAction != npsp.TDTM_Runnable.Action.AfterUpdate) {
            return dmlWrapper;
        }

        Map<Id, SObject> oldById = oldList != null
            ? new Map<Id, SObject>(oldList)
            : new Map<Id, SObject>();

        List<Task> tasksToInsert = new List<Task>();

        for (SObject sObj : newList) {
            Opportunity opp = (Opportunity) sObj;

            if (!isQualified(opp)) {
                continue;
            }

            if (triggerAction == npsp.TDTM_Runnable.Action.AfterInsert) {
                tasksToInsert.add(buildTask(opp));
            } else {
                Opportunity oldOpp = oldById.get(opp.Id) == null
                    ? null
                    : (Opportunity) oldById.get(opp.Id);

                if (oldOpp == null || !isQualified(oldOpp)) {
                    tasksToInsert.add(buildTask(opp));
                }
            }
        }

        dmlWrapper.objectsToInsert.addAll(tasksToInsert);
        return dmlWrapper;
    }

    private Boolean isQualified(Opportunity opp) {
        return opp.IsWon == true
            && opp.Amount != null
            && opp.Amount >= 5000;
    }

    private Task buildTask(Opportunity opp) {
        return new Task(
            Subject = 'Major gift thank-you call',
            Priority = 'High',
            Status = 'Not Started',
            WhatId = opp.Id,
            WhoId = opp.npsp__Primary_Contact__c,
            OwnerId = opp.OwnerId,
            ActivityDate = opp.CloseDate.addDays(3)
        );
    }
}
