public with sharing class TA_Account_CreateOnboardingTask extends TriggerAction {
    public override void afterInsert(List<SObject> newList) {
        List<Account> accounts = (List<Account>) newList;
        Set<String> qualifyingTypes = new Set<String>{
            'Customer - Direct',
            'Customer - Channel'
        };

        List<Task> tasksToInsert = new List<Task>();

        for (Account acc : accounts) {
            if (qualifyingTypes.contains(acc.Type)) {
                tasksToInsert.add(
                    new Task(
                        Subject = 'Onboard new customer',
                        WhatId = acc.Id,
                        OwnerId = acc.OwnerId,
                        ActivityDate = System.today().addDays(7),
                        Status = 'Not Started',
                        Priority = 'Normal'
                    )
                );
            }
        }

        if (!tasksToInsert.isEmpty()) {
            insert tasksToInsert;
        }
    }
}
