public class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        TriggerActionHandler.bypass('Account');
        try {
            if (accountIds == null || accountIds.isEmpty()) {
                return;
            }

            List<Account> accounts = [
                SELECT Id
                FROM Account
                WHERE Id IN :accountIds
            ];

            if (accounts.isEmpty()) {
                return;
            }

            for (Account account : accounts) {
                account.OwnerId = newOwnerId;
            }

            List<Contact> contacts = [
                SELECT Id
                FROM Contact
                WHERE AccountId IN :accountIds
            ];

            for (Contact contact : contacts) {
                contact.OwnerId = newOwnerId;
            }

            update accounts;
            if (!contacts.isEmpty()) {
                update contacts;
            }
        } finally {
            TriggerActionHandler.clearBypass('Account');
        }
    }
}
