public inherited sharing class TA_Case_RollupOpenCount implements TriggerActionHandler {

    public void handleTrigger(
        List<SObject> triggerNew,
        List<SObject> triggerOld,
        Map<Id, SObject> triggerNewMap,
        Map<Id, SObject> triggerOldMap,
        TriggerActionContext context
    ) {
        performRollup((List<Case>) triggerNew, (List<Case>) triggerOld);
    }

    private void performRollup(List<Case> newCases, List<Case> oldCases) {
        Map<Id, Integer> deltas = new Map<Id, Integer>();

        if (newCases != null) {
            for (Case caseRecord : newCases) {
                if (caseRecord.AccountId != null && !caseRecord.IsClosed) {
                    addDelta(deltas, caseRecord.AccountId, 1);
                }
            }
        }

        if (oldCases != null) {
            for (Case caseRecord : oldCases) {
                if (caseRecord.AccountId != null && !caseRecord.IsClosed) {
                    addDelta(deltas, caseRecord.AccountId, -1);
                }
            }
        }

        if (deltas.isEmpty()) {
            return;
        }

        Map<Id, Account> accountsById = new Map<Id, Account>(
            [SELECT Id, FB_Open_Case_Count__c FROM Account WHERE Id IN :deltas.keySet()]
        );

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : deltas.keySet()) {
            Account account = accountsById.get(accountId);
            if (account == null) {
                continue;
            }

            Decimal currentCount = account.FB_Open_Case_Count__c;
            Boolean wasNull = currentCount == null;
            if (wasNull) {
                currentCount = 0;
            }

            Decimal newCount = currentCount + deltas.get(accountId);
            if (newCount < 0) {
                newCount = 0;
            }

            Integer delta = deltas.get(accountId);
            if (delta != 0 && (wasNull || newCount != currentCount)) {
                account.FB_Open_Case_Count__c = newCount;
                accountsToUpdate.add(account);
            }
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }

    private void addDelta(Map<Id, Integer> deltas, Id accountId, Integer amount) {
        Integer current = deltas.get(accountId);
        deltas.put(accountId, (current == null ? 0 : current) + amount);
    }
}
